-- 0219: Añade 9 castillos cuyo municipio ya existía en la BD (grafía/bilingüe distinta)

INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES ('24033','torre','Torre de Carchelejo (Castillejo)','Siglo XIV. Atalaya fronteriza troncocónica edificada en mampostería regular caliza. Situada sobre un cerro escarpado de Sierra Mágina, servía de enlace visual y óptico con los castillos de Cambil y de la Guardia de Jaén.','inventario_castillos_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES ('13001','torre','Torreón del Gran Prior (Torreón de Don Juan José de Austria)','Siglo XIV. Sólido y monumental torreón del homenaje que formaba parte del palacio fortificado del Gran Priorato de la Orden de San Juan de Jerusalén en La Mancha. Estructura exenta de planta cuadrada construida en excelente sillería de piedra arenisca roja (rodeno), con tres plantas abovedadas góticas, ventanas ajimezadas y ladroneras defensivas superiores con garitones.','inventario_castillos_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES ('17066','castillo','Castillo de San Fernando (Castell de Sant Ferran)','Siglo XVIII (1753-1766). Monumento Nacional. Es considerado de forma unánime la fortaleza abaluartada más grande de Europa continental y una obra maestra cumbre de la ingeniería militar ilustrada mundial, proyectada por el ingeniero militar Juan Martín Cermeño bajo el reinado de Fernando VI para asegurar la frontera pirenaica tras el Tratado de los Pirineos. Presenta una inexpugnable e intacta planta estrellada poligonal de sillería regular caliza limpia de dimensiones monumentales (perímetro de 3,12 kilómetros) provista de colosales baluartes en punta de flecha con fosos profundos excavados, casamatas, una intrincada red de minas y contraminas subterráneas, y unos colosales aljibes abovedados interiores bajo el patio de armas con capacidad para 9 millones de litros de agua.','inventario_castillos_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES ('17132','castillo','Castillo-Palacio de Peralada','Siglos XIV-XIX. Centro residencial fortificado e hito de la arquitectura civil-militar de los vizcondes de Rocabertí en el Alt Empordà. El edificio actual combina la fisonomía exterior de una gran fortaleza militar rectangular de sillería caliza dorada regular y mampostería gruesa flanqueada por dos monumentales torres cilíndricas angulares almenadas con matacanes poligonales (siglo XIV), con una suntuosa fachada de estilo renacentista francés añadida en el siglo XIX.','inventario_castillos_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES ('07010','muralla','Castillo y Recinto Amurallado de Dalt Vila','Siglos X-XVI. Monumento Nacional y Patrimonio de la Humanidad. Es considerado de forma unánime uno de los conjuntos de fortificación abaluartada renacentista mejor conservados y más imponentes de la cuenca mediterránea, alzado originalmente como alcazaba islámica y transformado por Carlos V y Felipe II bajo la dirección de los ingenieros italianos Giovanni Battista Calvi y Jacobo Fratín. Presenta planta rectangular regular poligonal de dimensiones colosales que corona el cerro, protegida por siete potentes baluartes en punta de flecha ejecutados en sillería caliza dorada regular limpia de gran espesor diseñados para resistir artillería pesada, casamatas, foso y puertas fortificadas monumentales (Portal de ses Taules).','inventario_castillos_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES ('07013','fortaleza','Fortaleza de la Mola (Fortaleza de Isabel II)','Siglo XIX (1850-1875). Colosal complejo y obra cumbre de la arquitectura defensiva e ingeniería militar decimonónica en el Mediterráneo, alzado en excelente sillería regular caliza calórea para blindar la entrada del puerto de Mahón. Presenta planta poligonal de dimensiones monumentales adaptada al uso intensivo de la artillería de gran calibre y fusilería moderna, dotada de frentes fortificados con un foso perimetral profundo de más de dos kilómetros tallado en roca viva, caponeras, polvorines abovedados, galerías de tiro subterráneas y casamatas avanzadas.','inventario_castillos_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES ('07013','castillo','Castillo de San Felipe (Castell de Sant Felip - Restos)','Siglo XVI (1554-1555). Proyectado originalmente por Juan Bautista Calvi en el sistema abaluartado de planta estrellada para resistir los bombardeos de las armadas otomanas. Destruido en el siglo XVIII tras los sucesivos asedios franco-españoles y británicos, hoy subsiste su impresionante e intrincada red de galerías y contraminas subterráneas excavadas de forma virgen bajo la roca caliza calórea litoral.','inventario_castillos_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES ('36053','castillo','Castillo de Soutomaior','Siglos XII-XV. Monumento Nacional. Obra cumbre de la arquitectura de fortificación señorial-palaciega gallega y cuna del célebre y temido caudillo militar Pedro Madruga (Pedro Álvarez de Sotomayor) durante las guerras irmandiñas y dinásticas. Presenta planta rectangular regular inexpugnable que corona el cerro escarpado dominando el valle del río Verdugo, protegida por un doble recinto amurallado de sillería de granito regular limpia de gran espesor provisto de adarves transitables y foso. Destaca por su monumental e independiente Torre del Homenaje de planta cuadrada integrada en los lienzos y un palacio residencial interior con galerías neogóticas posteriores.','inventario_castillos_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES ('08058','castillo','Castillo de Castellet','Siglos XII-XV. Fortaleza señorial alzada en sillería de piedra caliza regular sobre un cerro escarpado que hoy domina el embalse de Foix. Presenta planta rectangular regular almenada compacta defendida por una robusta e independiente Torre del Homenaje de planta circular del siglo XII y una barbacana exterior con muros saeteras.','inventario_castillos_pdf',date('now'));
